import{_ as t,o as s,c as a,a5 as i}from"./chunks/framework.UjrY2eRK.js";const p=JSON.parse('{"title":"Publish versioned user documentation with VitePress and GitHub Pages","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/adr/0021-publish-versioned-user-documentation.md","filePath":"architecture/adr/0021-publish-versioned-user-documentation.md","lastUpdated":1788123021000}'),o={name:"architecture/adr/0021-publish-versioned-user-documentation.md"};function r(n,e,d,u,c,l){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="publish-versioned-user-documentation-with-vitepress-and-github-pages" tabindex="-1">Publish versioned user documentation with VitePress and GitHub Pages <a class="header-anchor" href="#publish-versioned-user-documentation-with-vitepress-and-github-pages" aria-label="Permalink to &quot;Publish versioned user documentation with VitePress and GitHub Pages&quot;">​</a></h1><p>User and operator documentation is authored as canonical Markdown under <code>docs/</code>, built by the <code>push-gateway-docs</code> Nx project with stable VitePress, and published at the repository&#39;s GitHub project Pages URL. The site uses local search and assets without analytics or other third-party browser requests.</p><p>The <code>/next/</code> channel follows validated <code>master</code> commits. <code>/latest/</code> follows the newest stable release, while <code>/vX.Y.Z/</code> is generated once from the corresponding verified Release Please tag and never overwritten. Generated output is retained on an orphan <code>pages-history</code> branch, but GitHub Actions remains the Pages publishing source. Build, history assembly, and deployment use separate least-privilege jobs, and concurrent publications are serialized.</p><p>This preserves exact historical output without duplicating authored Markdown, rebuilding every old tag, or trusting a community versioning plugin. Internal agent documentation stays unpublished, and all Trinity client implementation remains outside this repository.</p>',4)])])}const m=t(o,[["render",r]]);export{p as __pageData,m as default};
